#include "../../../reference/pari/src/basemath/mpqs.c"
#include <stdio.h>
static void snapshot(mpqs_handle_t*h){pari_printf("[%Ps,%Ps,%u,%u,%u,%d,[",h->A,h->B,h->bin_index,h->index_i,h->index_j,h->index2_FB);for(long j=0;j<h->omega_A;j++){if(j)printf(",");pari_printf("[%d,%Ps]",h->per_A_pr[j]._i,h->per_A_pr[j]._H);}printf("],[");for(long j=3;j<=h->size_of_FB+1;j++){mpqs_FB_entry_t*f=h->FB+j;if(j>3)printf(",");printf("[%u,%d,%d,%u,%u]",f->fbe_p,f->fbe_start1,f->fbe_start2,f->fbe_logval,f->fbe_flags);}printf("],\"");for(long j=0;j<2*h->M;j++)printf("%02x",h->sieve_array[j]);printf("\",[");long n=mpqs_eval_sieve(h);for(long j=0;j<n;j++){if(j)printf(",");printf("%ld",h->candidates[j]);}printf("]]");}
int main(){char*line=NULL;size_t cap=0;pari_init(256000000,500000);while(getline(&line,&cap,stdin)>0){pari_sp av=avma;GEN a=gp_read_str(line);mpqs_handle_t h={0};long ok=mpqs_class_init(&h,gel(a,1),itos(gel(a,2))),rounds=itos(gel(a,3));GEN v=gel(a,4),missing=NULL;if(lg(v)>1){missing=cgetg(lg(v),t_VECSMALL);for(long i=1;i<lg(v);i++)missing[i]=itos(gel(v,i));}printf("OK [%ld,%d,%d,%d,%d,%u,%u,[",ok,h.two_is_norm,h.two_is_bad,h.size_of_FB,h.index1_FB,h.largest_FB_p,h.sieve_threshold);for(long i=3;i<=h.size_of_FB+1;i++){mpqs_FB_entry_t*f=h.FB+i;if(i>3)printf(",");printf("[%u,%u,%u]",f->fbe_p,f->fbe_sqrt_kN,f->fbe_flags);}printf("],[");if(ok){h.index_j=(mpqs_uint32_t)-1;h.candidates=(long*)stack_malloc(2016*sizeof(long));for(long i=0;i<rounds;i++){if(i)printf(",");ok=mpqs_self_init(&h,missing);if(!ok){printf("0");break;}mpqs_sieve(&h);snapshot(&h);}}printf("]]\n");set_avma(av);fflush(stdout);}pari_close();}
